INSERT IGNORE INTO `product_content` (`product_id`, `features`, `highlights`, `key_features`, `ideal_for`, `love_it`, `specifications`, `updated_at`) VALUES ('100','[\"Waterproof design keeps clothes dry during play or potty training\",\"Soft, breathable fabric for all-day comfort\",\"Lightweight with cute, playful prints\"]','[\"Keeps kids dry and comfortable\",\"Fun prints kids will love\"]','[{\"title\":\"Waterproof Protection\",\"desc\":\"Keeps clothes dry during playtime or potty training\"},{\"title\":\"Breathable Comfort\",\"desc\":\"Soft, lightweight fabric for everyday wear\"}]','Toddlers and young kids during potty training or active outdoor play.','[\"Keeps clothes dry\",\"Comfortable all day\",\"Cute, playful design\"]','[{\"label\":\"Material\",\"value\":\"Soft, breathable waterproof fabric\"},{\"label\":\"Recommended For\",\"value\":\"Toddlers and young kids\"}]','2026-09-17 06:39:54'),('101','[\"Adhesive mounting — no drilling required\",\"Multiple hooks keep tools and accessories organized\",\"Sleek design suits kitchens and bathrooms\"]','[\"Strong adhesive hold for everyday items\",\"Space-saving multi-hook design\"]','[{\"title\":\"Adhesive Mounting\",\"desc\":\"Easy to install without drilling or tools\"},{\"title\":\"Multi-Hook Design\",\"desc\":\"Keeps accessories organized and within reach\"}]','Kitchens, bathrooms, and any space that needs smarter organization.','[\"No drilling needed\",\"Keeps things organized\",\"Sleek, space-saving design\"]','[{\"label\":\"Mounting Type\",\"value\":\"Adhesive (no drilling required)\"},{\"label\":\"Use\",\"value\":\"Kitchen or bathroom wall organizer\"}]','2026-09-17 06:39:54'),('102','[\"Food-grade silicone and stainless steel mesh for safe brewing\",\"Fun figure shape hangs conveniently on your cup\",\"Reusable — skip the disposable tea bags\"]','[\"Safe, food-grade materials\",\"Charming design makes tea time more fun\"]','[{\"title\":\"Food-Grade Materials\",\"desc\":\"Silicone and stainless steel mesh, safe for daily use\"},{\"title\":\"Convenient Hanging Design\",\"desc\":\"Hangs on the cup edge while steeping\"}]','Tea lovers who want a reusable, fuss-free way to brew loose-leaf tea.','[\"Reusable and eco-friendly\",\"Fun, charming design\",\"Easy to clean\"]','[{\"label\":\"Material\",\"value\":\"Food-grade silicone and stainless steel mesh\"},{\"label\":\"Type\",\"value\":\"Hanging tea infuser\"}]','2026-09-17 06:39:54'),('103','[\"Colorful design keeps kids engaged while learning\",\"Reusable — practice again and again\",\"Great for home, school, or tutoring sessions\"]','[\"Makes learning multiplication fun and interactive\",\"Builds confidence with numbers\"]','[{\"title\":\"Reusable Design\",\"desc\":\"Practice multiplication tables again and again\"},{\"title\":\"Kid-Friendly\",\"desc\":\"Colorful, interactive layout keeps children engaged\"}]','Parents, teachers, and tutors helping kids build math confidence.','[\"Makes math fun\",\"Reusable and durable\",\"Builds real confidence\"]','[{\"label\":\"Type\",\"value\":\"Reusable multiplication table sheet\"},{\"label\":\"Recommended For\",\"value\":\"Kids learning multiplication\"}]','2026-09-17 06:39:54'),('133','[\"Classic 5x5 frame perfectly sized for square photos\",\"Sturdy build to protect and display your memories\",\"Simple, elegant design suits any decor style\",\"Stands on a shelf or hangs on a wall\"]','[\"Fits standard 5x5 photos perfectly\",\"Timeless design for home or office\",\"Doubles as a thoughtful gift\"]','[{\"title\":\"5x5 Fit\",\"desc\":\"Sized specifically for 5x5 photos - no cropping needed\"},{\"title\":\"Sturdy Construction\",\"desc\":\"Built to protect your photo and stand the test of time\"},{\"title\":\"Flexible Display\",\"desc\":\"Can be placed on a shelf or hung on a wall\"}]','Displaying favorite memories at home, in the office, or as a thoughtful gift.','[\"Perfect square fit\",\"Timeless design\",\"Great gift idea\",\"Flexible display options\"]','[{\"label\":\"Frame Size\",\"value\":\"5 x 5 inches\"},{\"label\":\"Display Style\",\"value\":\"Stands on a shelf or hangs on a wall\"},{\"label\":\"Package Includes\",\"value\":\"1 x Photo Frame\"}]','2026-09-17 06:39:54'),('136','[\"Sleek bar-style pendant for modern interiors\",\"Adds a stylish focal point above tables or counters\",\"Fixture only — pair with your preferred bulb\",\"Simple installation for a quick decor upgrade\"]','[\"Modern, minimalist bar design\",\"Elevates kitchen, dining, or bar area decor\",\"Versatile fixture that suits multiple bulb styles\"]','[{\"title\":\"Modern Design\",\"desc\":\"Clean bar silhouette suits contemporary interiors\"},{\"title\":\"Versatile Placement\",\"desc\":\"Great over kitchen islands, dining tables, or home bars\"},{\"title\":\"Fixture Only\",\"desc\":\"Lets you choose the bulb style and warmth that fits your space\"}]','Kitchens, dining areas, and home bars looking for a modern lighting upgrade.','[\"Sleek modern look\",\"Great statement piece\",\"Choose your own bulb\",\"Fits multiple spaces\"]','[{\"label\":\"Style\",\"value\":\"Bar pendant light fixture\"},{\"label\":\"Includes Bulb\",\"value\":\"No — fixture only\"},{\"label\":\"Package Includes\",\"value\":\"1 x Bar Pendant Fixture\"}]','2026-09-17 06:39:54'),('137','[\"Space-saving hanging design keeps floors clear\",\"Durable construction built for everyday laundry use\",\"Easy to mount on doors, walls, or hooks\",\"Breathable design helps reduce odor and dampness\"]','[\"Maximizes small laundry spaces\",\"Keeps dirty clothes organized and out of sight\",\"Sturdy enough for daily use\"]','[{\"title\":\"Space-Saving\",\"desc\":\"Hangs on doors or walls to free up valuable floor space\"},{\"title\":\"Durable Build\",\"desc\":\"Made to handle daily laundry loads without sagging\"},{\"title\":\"Breathable Design\",\"desc\":\"Helps air circulate to keep clothes fresher for longer\"}]','Small apartments, laundry rooms, dorms, and anyone short on floor space.','[\"Frees up floor space\",\"Keeps laundry organized\",\"Simple to install\",\"Sturdy everyday use\"]','[{\"label\":\"Type\",\"value\":\"Hanging laundry basket / hamper\"},{\"label\":\"Mounting\",\"value\":\"Hangs on doors, walls, or hooks\"},{\"label\":\"Package Includes\",\"value\":\"1 x Hanging Laundry Basket\"}]','2026-09-17 06:39:54'),('138','[\"Eagle-shaped decorative light for a striking display\",\"Adds a warm ambient glow to any room\",\"Lightweight design, easy to place or mount\",\"Doubles as a statement decor piece even when switched off\"]','[\"Unique eagle silhouette stands out as a centerpiece\",\"Creates a warm, inviting atmosphere\",\"Great conversation-starter decor piece\"]','[{\"title\":\"Eye-Catching Design\",\"desc\":\"Bold eagle silhouette makes a striking decorative statement\"},{\"title\":\"Ambient Glow\",\"desc\":\"Soft lighting ideal for living rooms, bedrooms, or offices\"},{\"title\":\"Easy Setup\",\"desc\":\"Ready to use right out of the box\"}]','Home decor enthusiasts, nature lovers, and anyone looking for a unique accent light.','[\"Striking eagle design\",\"Warm ambient glow\",\"Easy to set up\",\"Unique gift idea\"]','[{\"label\":\"Design\",\"value\":\"Eagle-shaped decorative light\"},{\"label\":\"Use\",\"value\":\"Home or office accent lighting\"},{\"label\":\"Package Includes\",\"value\":\"1 x Eagle Light\"}]','2026-09-17 06:39:54'),('139','[\"Challenges memory, logic, and problem-solving skills\",\"Fun, screen-free activity for the whole family\",\"Compact size ÔÇö easy to carry and store\",\"Encourages focus and patience during play\"]','[\"Keeps the mind active and engaged\",\"A great alternative to screen time\",\"Fun for both kids and adults\"]','[{\"title\":\"Brain Training\",\"desc\":\"Designed to exercise memory and logical thinking\"},{\"title\":\"Portable Design\",\"desc\":\"Compact size makes it easy to take anywhere\"},{\"title\":\"Family-Friendly\",\"desc\":\"Simple enough for kids, engaging enough for adults\"}]','Kids, students, and adults who enjoy a fun mental challenge ÔÇö great for game nights, travel, or downtime.','[\"Screen-free entertainment\",\"Sharpens the mind\",\"Compact and portable\",\"Makes a thoughtful gift\"]','[{\"label\":\"Type\",\"value\":\"Puzzle / brain-training game\"},{\"label\":\"Recommended For\",\"value\":\"Kids and adults\"},{\"label\":\"Package Includes\",\"value\":\"1 x Mind Sharpening Game\"}]','2026-09-23 11:25:36'),('99','[\"Sleek square black dial for a modern look\",\"Durable stainless-steel strap built for daily wear\",\"Comes with 3 months warranty\"]','[\"Blends elegance with everyday durability\",\"Suits both casual and formal occasions\"]','[{\"title\":\"Modern Design\",\"desc\":\"Square black dial with a clean, contemporary look\"},{\"title\":\"Durable Strap\",\"desc\":\"Stainless-steel band built to last\"}]','Anyone wanting a stylish watch that works for both casual and formal wear.','[\"Elegant, modern design\",\"Versatile for any occasion\",\"3 months warranty included\"]','[{\"label\":\"Dial Shape\",\"value\":\"Square, black dial\"},{\"label\":\"Strap Material\",\"value\":\"Stainless steel\"},{\"label\":\"Warranty\",\"value\":\"3 months\"}]','2026-09-17 06:39:54');
